package com.abhijit.gamesolution;

import android.app.Notification;import android.app.NotificationChannel;import android.app.NotificationManager;import android.app.Service;import android.content.Context;import android.content.Intent;import android.content.pm.ApplicationInfo;import android.graphics.Color;import android.graphics.PixelFormat;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Build;import android.os.IBinder;import android.os.VibrationEffect;import android.os.Vibrator;import android.os.VibratorManager;import android.provider.Settings;import android.view.Gravity;import android.view.MotionEvent;import android.view.View;import android.view.WindowManager;import android.view.animation.DecelerateInterpolator;import android.widget.LinearLayout;import android.widget.SeekBar;import android.widget.TextView;import android.widget.Toast;

public class FloatingService extends Service {
 private static final String CHANNEL_ID="game_solution_overlay";private static final int MENU_WIDTH_DP=292,MENU_GAP_DP=10,DELETE_ZONE_SIZE_DP=76,DELETE_TRIGGER_RADIUS_DP=72;private WindowManager windowManager;private View bubbleView,menuView,deleteZoneView;private String targetPackage;private boolean dragging,deleteZoneActive;private float downX,downY;private int startX,startY;private final int navy=Color.rgb(16,21,34),card=Color.rgb(28,35,52),text=Color.rgb(245,247,252),secondary=Color.rgb(165,174,194),primary=Color.rgb(105,145,255),danger=Color.rgb(255,105,120);
 @Override public void onCreate(){super.onCreate();createChannel();startForeground(10,buildNotification());if(Settings.canDrawOverlays(this))showBubble();else stopSelf();}
 private Notification buildNotification(){return new Notification.Builder(this,CHANNEL_ID).setContentTitle("GameSolution").setContentText("Floating restart bubble is active").setSmallIcon(android.R.drawable.ic_menu_rotate).setOngoing(true).build();}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL_ID,"GameSolution",NotificationManager.IMPORTANCE_LOW));}
 private void showBubble(){windowManager=(WindowManager)getSystemService(WINDOW_SERVICE);int size=BubbleSettings.getSize(this);TextView bubble=new TextView(this);bubble.setText("i");bubble.setTextColor(Color.WHITE);bubble.setTextSize(30);bubble.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bubble.setGravity(Gravity.CENTER);bubble.setIncludeFontPadding(false);GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(125,155,255),Color.rgb(72,91,205)});bg.setShape(GradientDrawable.OVAL);bg.setStroke(dp(2),Color.argb(80,255,255,255));bubble.setBackground(bg);bubble.setAlpha(BubbleSettings.getTransparency(this)/100f);bubble.setElevation(14f);final WindowManager.LayoutParams params=new WindowManager.LayoutParams(dp(size),dp(size),overlayType(),WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.START;int sw=getResources().getDisplayMetrics().widthPixels,sh=getResources().getDisplayMetrics().heightPixels;if(BubbleSettings.hasPosition(this)){params.x=clamp((int)(BubbleSettings.getPositionX(this)*sw),dp(4),sw-dp(size+4));params.y=clamp((int)(BubbleSettings.getPositionY(this)*sh),dp(48),sh-dp(size+8));}else{params.x=sw-dp(size+12);params.y=dp(220);}
  bubble.setOnTouchListener((v,e)->{switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:dragging=false;deleteZoneActive=false;downX=e.getRawX();downY=e.getRawY();startX=params.x;startY=params.y;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-downX,dy=e.getRawY()-downY;if(Math.abs(dx)>dp(6)||Math.abs(dy)>dp(6)){if(!dragging){dragging=true;vibrate(12);dismissAllOverlays();showDeleteZone();}}params.x=clamp(startX+(int)dx,dp(4),sw-dp(size+4));params.y=clamp(startY+(int)dy,dp(48),sh-dp(size+8));windowManager.updateViewLayout(bubble,params);if(dragging)updateDeleteZoneState(params.x,params.y,size);return true;case MotionEvent.ACTION_UP:if(dragging){boolean remove=deleteZoneActive;vibrate(remove?35:12);if(remove){animateDeleteAndStop(bubble);return true;}hideDeleteZone();if(BubbleSettings.isSnapToEdge(this)){snapToEdge(params,size,sw);}else savePosition(params,sw,sh,size);return true;}vibrate(18);if(LiveMonitorDialog.isShowing()){LiveMonitorDialog.dismiss();return true;}if(AppDetailInfoDialog.isShowing()){AppDetailInfoDialog.dismissFromBubbleTap();return true;}if(menuView!=null){removeMenu();return true;}openMenu(params.x,params.y,size);return true;}return false;});bubbleView=bubble;windowManager.addView(bubbleView,params);}
 private void savePosition(WindowManager.LayoutParams p,int sw,int sh,int size){BubbleSettings.setPosition(this,p.x/(float)sw,p.y/(float)sh);}
 private void snapToEdge(WindowManager.LayoutParams p,int size,int sw){int target=(p.x+dp(size)/2<sw/2)?dp(4):sw-dp(size+4);View b=bubbleView;final int y=p.y;final int from=p.x;android.animation.ValueAnimator a=android.animation.ValueAnimator.ofInt(from,target);a.setDuration(220);a.setInterpolator(new DecelerateInterpolator());a.addUpdateListener(v->{p.x=(Integer)v.getAnimatedValue();try{windowManager.updateViewLayout(b,p);}catch(Exception ignored){}});a.addListener(new android.animation.AnimatorListenerAdapter(){@Override public void onAnimationEnd(android.animation.Animator animation){BubbleSettings.setPosition(FloatingService.this,p.x/(float)sw,p.y/(float)getResources().getDisplayMetrics().heightPixels);}});a.start();}
 private void dismissAllOverlays(){LiveMonitorDialog.dismiss();AppDetailInfoDialog.dismiss();removeMenu();}
 private boolean isBubbleTouch(MotionEvent e){if(bubbleView==null)return false;int[] p=new int[2];bubbleView.getLocationOnScreen(p);float x=e.getRawX(),y=e.getRawY();return x>=p[0]&&x<=p[0]+bubbleView.getWidth()&&y>=p[1]&&y<=p[1]+bubbleView.getHeight();}
 private void showDeleteZone(){if(deleteZoneView!=null)return;TextView z=new TextView(this);z.setText("×");z.setTextColor(Color.WHITE);z.setTextSize(30);z.setTypeface(Typeface.DEFAULT,Typeface.BOLD);z.setGravity(Gravity.CENTER);z.setBackground(round(Color.rgb(95,31,43),40));z.setElevation(18f);z.setAlpha(0f);z.setScaleX(.65f);z.setScaleY(.65f);WindowManager.LayoutParams p=new WindowManager.LayoutParams(dp(DELETE_ZONE_SIZE_DP),dp(DELETE_ZONE_SIZE_DP),overlayType(),WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;p.y=dp(30);deleteZoneView=z;windowManager.addView(z,p);z.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(180).setInterpolator(new DecelerateInterpolator()).start();}
 private void updateDeleteZoneState(int x,int y,int size){if(deleteZoneView==null)return;int sw=getResources().getDisplayMetrics().widthPixels,sh=getResources().getDisplayMetrics().heightPixels;float bx=x+dp(size)/2f,by=y+dp(size)/2f,zcx=sw/2f,zcy=sh-dp(30)-dp(DELETE_ZONE_SIZE_DP)/2f;boolean active=Math.hypot(bx-zcx,by-zcy)<=dp(DELETE_TRIGGER_RADIUS_DP);if(active==deleteZoneActive)return;deleteZoneActive=active;if(active){vibrate(28);deleteZoneView.animate().scaleX(1.25f).scaleY(1.25f).setDuration(120).start();deleteZoneView.setBackground(round(danger,40));((TextView)deleteZoneView).setText("🗑");}else{deleteZoneView.animate().scaleX(1f).scaleY(1f).setDuration(120).start();deleteZoneView.setBackground(round(Color.rgb(95,31,43),40));((TextView)deleteZoneView).setText("×");}}
 private void animateDeleteAndStop(View bubble){hideDeleteZone();bubble.animate().alpha(0f).scaleX(.2f).scaleY(.2f).setDuration(180).setInterpolator(new DecelerateInterpolator()).withEndAction(this::stopSelf).start();}
 private void hideDeleteZone(){if(deleteZoneView==null||windowManager==null)return;View z=deleteZoneView;deleteZoneView=null;z.animate().alpha(0f).scaleX(.65f).scaleY(.65f).setDuration(120).withEndAction(()->{try{windowManager.removeView(z);}catch(Exception ignored){}}).start();deleteZoneActive=false;}
 private void openMenu(int bx,int by,int size){removeMenu();targetPackage=ForegroundAppResolver.getPreviousPackage(this,getPackageName());if(targetPackage==null){Toast.makeText(this,"Unable to identify foreground app. Allow Usage Access.",Toast.LENGTH_SHORT).show();return;}LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(14),dp(18),dp(14));box.setBackground(round(navy,20));box.setElevation(22f);TextView title=label(getAppLabel(targetPackage),17,text,Typeface.BOLD);box.addView(label("CURRENT APP",11,primary,Typeface.BOLD));LinearLayout titleRow=new LinearLayout(this);titleRow.setGravity(Gravity.CENTER_VERTICAL);titleRow.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView settings=label("⚙",21,secondary,Typeface.BOLD);settings.setGravity(Gravity.CENTER);settings.setPadding(dp(8),0,0,0);titleRow.addView(settings,new LinearLayout.LayoutParams(dp(38),dp(38)));box.addView(titleRow);TextView pkg=label(targetPackage,11,secondary,Typeface.NORMAL);pkg.setSingleLine(true);pkg.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);pkg.setPadding(0,0,0,dp(10));box.addView(pkg);settings.setOnClickListener(v->{vibrate(20);showBubbleSettings();});LinearLayout restart=option("↻","Restart App","Clear task and relaunch",text);box.addView(restart,rowLp(dp(56),dp(6)));restart.setOnClickListener(v->{vibrate(25);String p=targetPackage;removeMenu();boolean ok=RestartExecutor.restart(this,p);if(!ok)Toast.makeText(this,"Unable to relaunch "+p,Toast.LENGTH_SHORT).show();});LinearLayout appSettings=option("⚙","App Settings","Open Android App Info",danger);box.addView(appSettings,rowLp(dp(56),dp(6)));appSettings.setOnClickListener(v->{vibrate(25);String p=targetPackage;removeMenu();if(!RestartExecutor.openForceStopPage(this,p))Toast.makeText(this,"Unable to open App Info for "+p,Toast.LENGTH_SHORT).show();});LinearLayout live=option("◉","Live Monitor","CPU, memory and activity status",primary);box.addView(live,rowLp(dp(56),dp(6)));live.setOnClickListener(v->{vibrate(20);String p=targetPackage;removeMenu();LiveMonitorDialog.show(this,windowManager,p,null);});LinearLayout appInfo=option("ⓘ","App Detail Info","View and share app information",primary);box.addView(appInfo,rowLp(dp(56),dp(6)));appInfo.setOnClickListener(v->{vibrate(20);AppDetailInfoDialog.show(this,targetPackage,windowManager,menuView,this::removeMenu);});LinearLayout recentApps=buildRecentAppsRow();box.addView(recentApps,rowLp(dp(54),0));int sw=getResources().getDisplayMetrics().widthPixels,mw=dp(MENU_WIDTH_DP),gap=dp(MENU_GAP_DP);boolean left=bx+dp(size/2)<sw/2;int mx=left?bx+dp(size)+gap:bx-mw-gap;mx=clamp(mx,dp(8),sw-mw-dp(8));int my=clamp(by,dp(48),getResources().getDisplayMetrics().heightPixels-dp(390));WindowManager.LayoutParams mp=new WindowManager.LayoutParams(mw,WindowManager.LayoutParams.WRAP_CONTENT,overlayType(),WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH,PixelFormat.TRANSLUCENT);mp.gravity=Gravity.TOP|Gravity.START;mp.x=mx;mp.y=my;box.setOnTouchListener((v,e)->{if(isBubbleTouch(e)){if(e.getActionMasked()==MotionEvent.ACTION_UP)removeMenu();return true;}if(e.getActionMasked()==MotionEvent.ACTION_OUTSIDE){removeMenu();return true;}return false;});menuView=box;windowManager.addView(menuView,mp);}
 private void showBubbleSettings(){removeMenu();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(22),dp(20),dp(22),dp(18));box.setBackground(round(card,22));box.addView(label("Bubble Settings",20,text,Typeface.BOLD));box.addView(label("Adjust the floating bubble",13,secondary,Typeface.NORMAL),rowLp(-2,dp(18)));TextView sv=label("Size: "+BubbleSettings.getSize(this)+"dp",14,text,Typeface.BOLD);box.addView(sv);SeekBar sb=new SeekBar(this);sb.setMax(40);sb.setProgress(BubbleSettings.getSize(this)-40);box.addView(sb,rowLp(-2,dp(14)));TextView av=label("Transparency: "+BubbleSettings.getTransparency(this)+"%",14,text,Typeface.BOLD);box.addView(av);SeekBar ab=new SeekBar(this);ab.setMax(80);ab.setProgress(BubbleSettings.getTransparency(this)-20);box.addView(ab,rowLp(-2,dp(12)));TextView snap=label("Snap to Edge: "+(BubbleSettings.isSnapToEdge(this)?"ON":"OFF"),14,text,Typeface.BOLD);snap.setGravity(Gravity.CENTER_VERTICAL);snap.setPadding(dp(12),0,dp(12),0);snap.setBackground(round(Color.rgb(38,46,66),14));snap.setOnClickListener(v->{boolean n=!BubbleSettings.isSnapToEdge(this);BubbleSettings.setSnapToEdge(this,n);snap.setText("Snap to Edge: "+(n?"ON":"OFF"));});box.addView(snap,rowLp(dp(48),dp(16)));sb.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean f){int n=40+p;sv.setText("Size: "+n+"dp");BubbleSettings.setSize(FloatingService.this,n);applyBubbleSettings();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});ab.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean f){int n=20+p;av.setText("Transparency: "+n+"%");BubbleSettings.setTransparency(FloatingService.this,n);applyBubbleSettings();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});TextView done=label("DONE",13,Color.WHITE,Typeface.BOLD);done.setGravity(Gravity.CENTER);done.setBackground(round(primary,16));done.setPadding(0,dp(14),0,dp(14));done.setOnClickListener(v->removeMenu());box.addView(done);WindowManager.LayoutParams p=new WindowManager.LayoutParams(dp(310),WindowManager.LayoutParams.WRAP_CONTENT,overlayType(),WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH,PixelFormat.TRANSLUCENT);p.gravity=Gravity.CENTER;box.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_OUTSIDE){removeMenu();return true;}return false;});menuView=box;windowManager.addView(menuView,p);}
 private void applyBubbleSettings(){if(bubbleView==null)return;int size=BubbleSettings.getSize(this);WindowManager.LayoutParams p=(WindowManager.LayoutParams)bubbleView.getLayoutParams();int old=Math.max(1,p.width);float cx=p.x+old/2f,cy=p.y+old/2f;p.width=dp(size);p.height=dp(size);p.x=Math.max(dp(4),Math.min((int)(cx-dp(size)/2f),getResources().getDisplayMetrics().widthPixels-dp(size+4)));p.y=Math.max(dp(48),Math.min((int)(cy-dp(size)/2f),getResources().getDisplayMetrics().heightPixels-dp(size+8)));windowManager.updateViewLayout(bubbleView,p);bubbleView.setAlpha(BubbleSettings.getTransparency(this)/100f);}
 private LinearLayout buildRecentAppsRow(){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,0,0,0);row.setBackground(round(card,15));int count=0;try{android.app.usage.UsageStatsManager usm=(android.app.usage.UsageStatsManager)getSystemService(Context.USAGE_STATS_SERVICE);long now=System.currentTimeMillis();java.util.List<android.app.usage.UsageStats> stats=usm==null?null:usm.queryUsageStats(android.app.usage.UsageStatsManager.INTERVAL_DAILY,now-86400000L,now);if(stats!=null){java.util.Collections.sort(stats,(a,b)->Long.compare(b.getLastTimeUsed(),a.getLastTimeUsed()));java.util.HashSet<String> added=new java.util.HashSet<>();for(android.app.usage.UsageStats s:stats){String p=s.getPackageName();if(p==null||p.equals(getPackageName())||p.equals(targetPackage)||!added.add(p))continue;Intent launch=getPackageManager().getLaunchIntentForPackage(p);if(launch==null)continue;TextView icon=label("",1,text,Typeface.NORMAL);icon.setGravity(Gravity.CENTER);try{android.graphics.drawable.Drawable d=getPackageManager().getApplicationIcon(p);d.setBounds(0,0,dp(54),dp(54));icon.setCompoundDrawables(null,d,null,null);}catch(Exception ignored){continue;}icon.setContentDescription(getAppLabel(p));final String pkgName=p;icon.setOnClickListener(v->{vibrate(20);removeMenu();try{Intent i=getPackageManager().getLaunchIntentForPackage(pkgName);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED);startActivity(i);}}catch(Exception ignored){}});row.addView(icon,new LinearLayout.LayoutParams(dp(54),dp(54)));if(++count>=4)break;TextView spacer=label("",1,text,Typeface.NORMAL);row.addView(spacer,new LinearLayout.LayoutParams(0,dp(54),1));}}}catch(SecurityException ignored){}catch(Exception ignored){}if(count==0)row.addView(label("No recent apps",12,secondary,Typeface.NORMAL),new LinearLayout.LayoutParams(-1,dp(54)));return row;}
 private LinearLayout option(String icon,String title,String subtitle,int color){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(10),0,dp(8),0);r.setBackground(round(card,15));r.setClickable(true);TextView i=label(icon,22,color,Typeface.BOLD);i.setGravity(Gravity.CENTER);r.addView(i,new LinearLayout.LayoutParams(dp(38),-1));LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setGravity(Gravity.CENTER_VERTICAL);c.addView(label(title,14,text,Typeface.BOLD));c.addView(label(subtitle,11,secondary,Typeface.NORMAL));r.addView(c,new LinearLayout.LayoutParams(0,-1,1));return r;}
 private LinearLayout.LayoutParams rowLp(int h,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,h);p.bottomMargin=dp(b);return p;}private TextView label(String v,float s,int c,int st){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);t.setTypeface(Typeface.DEFAULT,st);return t;}private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}private String getAppLabel(String p){try{ApplicationInfo i=getPackageManager().getApplicationInfo(p,0);return getPackageManager().getApplicationLabel(i).toString();}catch(Exception e){return p;}}private int overlayType(){return Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;}private int clamp(int v,int min,int max){return Math.max(min,Math.min(v,max));}private void vibrate(long d){try{if(Build.VERSION.SDK_INT>=31){VibratorManager m=(VibratorManager)getSystemService(Context.VIBRATOR_MANAGER_SERVICE);if(m!=null)m.getDefaultVibrator().vibrate(VibrationEffect.createOneShot(d,VibrationEffect.DEFAULT_AMPLITUDE));}else{Vibrator v=(Vibrator)getSystemService(Context.VIBRATOR_SERVICE);if(v!=null)v.vibrate(VibrationEffect.createOneShot(d,VibrationEffect.DEFAULT_AMPLITUDE));}}catch(Exception ignored){}}
 private void removeMenu(){if(menuView!=null&&windowManager!=null){try{windowManager.removeView(menuView);}catch(Exception ignored){}menuView=null;}}
 @Override public void onDestroy(){hideDeleteZone();LiveMonitorDialog.dismiss();AppDetailInfoDialog.dismiss();removeMenu();if(bubbleView!=null&&windowManager!=null){try{windowManager.removeView(bubbleView);}catch(Exception ignored){}bubbleView=null;}super.onDestroy();}
 private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}@Override public IBinder onBind(Intent i){return null;}
}